pub fn getPreVarsCount(mut in_txt: Tpl::Text, in_a_modelInfo: &SimCode::ModelInfo) -> Result<Tpl::Text> {
    ::match_deref::match_deref! { match in_a_modelInfo {
        i_modelInfo @ SimCode::ModelInfo { varInfo: SimCode::VarInfo { .. }, .. } => {
            let mut txt = in_txt;
            let mut txt_1;
            let mut ret_2;
            let mut txt_3;
            let mut ret_4;
            let mut txt_5;
            let mut ret_6;
            let mut ret_7;
            let mut ret_8;
            let mut l_allVarCount;
            txt_1 = numRealvars((*Tpl::emptyTxt).clone(), i_modelInfo)?;
            ret_2 = stringInt(Tpl::textString(txt_1)?)?;
            txt_3 = numIntvars((*Tpl::emptyTxt).clone(), i_modelInfo)?;
            ret_4 = stringInt(Tpl::textString(txt_3)?)?;
            txt_5 = numBoolvars((*Tpl::emptyTxt).clone(), i_modelInfo)?;
            ret_6 = stringInt(Tpl::textString(txt_5)?)?;
            ret_7 = intAdd(ret_4, ret_6);
            ret_8 = intAdd(ret_2, ret_7);
            l_allVarCount = Tpl::writeStr((*Tpl::emptyTxt).clone(), intString(ret_8))?;
            txt = Tpl::writeText(txt, l_allVarCount)?;
            Ok(txt)
        }
        _ => {
            let mut txt = in_txt;
            Ok(txt)
        }
        _ => Err("getPreVarsCount: no case matched"),
    } }
}

