pub fn partitionInfoInit(
    mut txt: Tpl::Text,
    mut a_numPartitions: i32,
    mut a_numStates: i32,
    a_stateActivators: &metamodelica::List<i32>,
) -> Result<Tpl::Text> {
    let mut l_stateActs;
    let mut out_txt;
    l_stateActs = Tpl::pushIter(
        (*Tpl::emptyTxt).clone(),
        metamodelica::Ref::new(Tpl::IterOptions {
            startIndex0: 0,
            empty: None,
            separator: Some(metamodelica::Ref::new(Tpl::StringToken::ST_NEW_LINE)),
            alignNum: 0,
            alignOfset: 0,
            alignSeparator: metamodelica::Ref::new(Tpl::StringToken::ST_NEW_LINE),
            wrapWidth: 0,
            wrapSeparator: metamodelica::Ref::new(Tpl::StringToken::ST_NEW_LINE),
        }),
    )?;
    l_stateActs = lm_373(l_stateActs, a_stateActivators)?;
    l_stateActs = Tpl::popIter(l_stateActs)?;
    out_txt = Tpl::writeTok(
        txt,
        metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST {
            strList: metamodelica::list![
                literal!("//partitioning of the system, all partitions are active at t0\n"),
                literal!("_dimPartitions = ")
            ],
            lastHasNewLine: false,
        }),
    )?;
    out_txt = Tpl::writeStr(out_txt, intString(a_numPartitions))?;
    out_txt = Tpl::writeTok(
        out_txt,
        metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST {
            strList: metamodelica::list![
                literal!(";\n"),
                literal!("_partitionActivation = new bool[_dimPartitions]();\n"),
                literal!("memset(_partitionActivation,true,_dimPartitions*sizeof(bool));\n"),
                literal!("_stateActivator = new int[")
            ],
            lastHasNewLine: false,
        }),
    )?;
    out_txt = Tpl::writeStr(out_txt, intString(a_numStates))?;
    out_txt = Tpl::writeTok(
        out_txt,
        metamodelica::Ref::new(Tpl::StringToken::ST_LINE {
            line: literal!("]();\n"),
        }),
    )?;
    out_txt = Tpl::writeText(out_txt, l_stateActs)?;
    Ok(out_txt)
}

