pub fn outDecl(mut txt: Tpl::Text, a_ty: &ArcStr, mut a_varDecls: Tpl::Text) -> Result<(Tpl::Text, Tpl::Text)> {
    let mut l_newVar;
    let mut out_a_varDecls;
    let mut out_txt;
    l_newVar = Tpl::writeTok(
        (*Tpl::emptyTxt).clone(),
        metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!("out") }),
    )?;
    out_a_varDecls = Tpl::writeStr(a_varDecls, a_ty.clone())?;
    out_a_varDecls = Tpl::writeTok(
        out_a_varDecls,
        metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!(" ") }),
    )?;
    out_a_varDecls = Tpl::writeText(out_a_varDecls, l_newVar.clone())?;
    out_a_varDecls = Tpl::writeTok(
        out_a_varDecls,
        metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!(";") }),
    )?;
    out_a_varDecls = Tpl::writeTok(out_a_varDecls, metamodelica::Ref::new(Tpl::StringToken::ST_NEW_LINE))?;
    out_txt = Tpl::writeText(txt, l_newVar)?;
    Ok((out_txt, out_a_varDecls))
}

