            (l_jacalgloopsolvers, a_extraFuncsNamespace, a_extraFuncsDecl, a_extraFuncs) = lm_1596(l_jacalgloopsolvers, a_JacobianMatrices, a_extraFuncsNamespace, a_extraFuncsDecl, a_extraFuncs, a_simCode, i_modelInfo)?;
