    let mut l_cref;
    let mut out_txt;
    l_type = CodegenCppCommon::expTypeShort((*Tpl::emptyTxt).clone(), a_ty)?;
    l_cref = CodegenCppCommon::contextArrayCref((*Tpl::emptyTxt).clone(), a_cr, a_context)?;
