pub fn algStmtForGeneric_impl(
    mut txt: Tpl::Text,
    a_exp: &metamodelica::Ref<DAE::Exp>,
    a_iterator: &ArcStr,
    a_type: &ArcStr,
    a_arrayType: &ArcStr,
    mut a_iterIsArray: bool,
    mut a_body: Tpl::Text,
    a_context: &SimCodeFunction::Context,
    mut a_varDecls: Tpl::Text,
    a_simCode: &metamodelica::Ref<SimCode::SimCode>,
    mut a_extraFuncs: Tpl::Text,
    mut a_extraFuncsDecl: Tpl::Text,
    mut a_extraFuncsNamespace: Tpl::Text,
    mut a_stateDerVectorName: Tpl::Text,
    mut a_useFlatArrayNotation: bool,
) -> Result<(
    Tpl::Text,
    Tpl::Text,
    Tpl::Text,
    Tpl::Text,
    Tpl::Text,
    Tpl::Text,
    Tpl::Text,
)> {
    let mut l_iterName;
    let mut l_preExp;
    let mut l_tmpVar;
    let mut l_evar;
    let mut out_a_extraFuncs;
    let mut out_a_extraFuncsDecl;
    let mut out_a_extraFuncsNamespace;
    let mut out_a_stateDerVectorName;
    let mut out_txt;
    let mut out_a_body;
    let mut out_a_varDecls;
    l_iterName = CodegenCppCommon::contextIteratorName((*Tpl::emptyTxt).clone(), a_iterator, a_context)?;
    l_preExp = (*Tpl::emptyTxt).clone();
    l_tmpVar = (*Tpl::emptyTxt).clone();
    (
        l_evar,
        l_preExp,
        l_tmpVar,
        out_a_extraFuncs,
        out_a_extraFuncsDecl,
        out_a_extraFuncsNamespace,
        out_a_stateDerVectorName,
    ) = CodegenCppCommon::daeExp(
        (*Tpl::emptyTxt).clone(),
        a_exp,
        a_context,
        l_preExp,
        l_tmpVar,
        a_simCode,
        a_extraFuncs,
        a_extraFuncsDecl,
        a_extraFuncsNamespace,
        a_stateDerVectorName,
        a_useFlatArrayNotation,
    )?;
    out_txt = Tpl::writeText(txt, l_preExp)?;
    out_txt = Tpl::softNewLine(out_txt)?;
    out_txt = Tpl::writeTok(
        out_txt,
        metamodelica::Ref::new(Tpl::StringToken::ST_STRING {
            value: literal!("FOREACH("),
        }),
    )?;
    out_txt = Tpl::writeStr(out_txt, a_type.clone())?;
    out_txt = Tpl::writeTok(
        out_txt,
        metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!(" ") }),
    )?;
    out_txt = Tpl::writeText(out_txt, l_iterName)?;
    out_txt = Tpl::writeTok(
        out_txt,
        metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!(", ") }),
    )?;
    out_txt = Tpl::writeText(out_txt, l_evar)?;
    out_txt = Tpl::writeTok(
        out_txt,
        metamodelica::Ref::new(Tpl::StringToken::ST_LINE {
            line: literal!(") {\n"),
        }),
    )?;
    out_txt = Tpl::pushBlock(out_txt, metamodelica::Ref::new(Tpl::BlockType::BT_INDENT { width: 2 }))?;
    out_txt = Tpl::writeText(out_txt, a_body.clone())?;
    out_txt = Tpl::softNewLine(out_txt)?;
    out_txt = Tpl::popBlock(out_txt)?;
    out_txt = Tpl::writeTok(
        out_txt,
        metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!("}") }),
    )?;
    out_a_body = a_body;
    out_a_varDecls = a_varDecls;
    Ok((
        out_txt,
        out_a_body,
        out_a_varDecls,
        out_a_extraFuncs,
        out_a_extraFuncsDecl,
        out_a_extraFuncsNamespace,
        out_a_stateDerVectorName,
    ))
}

